import { Effect, Schema } from 'effect'
import { Tool, Toolkit } from 'effect/ai'
import { type ShortcutContract, Shortcuts } from './shortcuts.ts'

// The swiss-due shortcut is generated by scripts/build-due-shortcut.ts; every op answers with a JSON array.
const SHORTCUT = 'swiss-due'

const Reminder = Schema.Struct({ title: Schema.String, dueDate: Schema.String })
const Titled = Schema.Struct({ title: Schema.String })
const Timer = Schema.Struct({ name: Schema.String })
const Name = Schema.String.check(Schema.isNonEmpty())
// Due stores a reminder's time as local wall-clock time to the minute, in this Mac's time zone (measured on Due
// 26.4.4), so tools take exactly that and pass it through. The only check needed is that the date exists: JS Date
// would roll "2026-02-30" forward to March 2, so the written fields must read back unchanged.
// This Effect version publishes neither `pattern` nor checks after a custom filter in the tool's JSON Schema, so
// the description is what tells an MCP client the format; it is attached before the date-exists filter.
const LocalDateTime = Schema.String.check(
  Schema.isPattern(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/, {
    message: 'must be YYYY-MM-DD HH:mm in local time',
  }),
)
  .annotate({
    description:
      'Local date and time on this Mac, to the minute, as YYYY-MM-DD HH:mm (e.g. 2026-10-17 09:30). Due resolves the hour that repeats when clocks fall back the same way its own app does.',
  })
  .check(
    Schema.makeFilter<string>((s) => {
      const [y, mo, d, h, mi] = s.split(/[- :]/).map(Number)
      const back = new Date(Date.UTC(y ?? 0, (mo ?? 1) - 1, d, h, mi))
      return back.getUTCFullYear() === y &&
        back.getUTCMonth() + 1 === mo &&
        back.getUTCDate() === d &&
        back.getUTCHours() === h &&
        back.getUTCMinutes() === mi
        ? undefined
        : `${s} does not exist`
    }),
  )

const ByTitle = { title: Name }
const ByTitleAt = { title: Name, dueDate: LocalDateTime }
const ByName = { name: Name }

const contract = <I extends Schema.Top, O extends Schema.Top>(
  input: I,
  output: O,
) => ({ name: SHORTCUT, input, output })

// A Find with no matches ends swiss-due before its output step, so Shortcuts prints nothing (measured on Due
// 26.4.4). Only the ops that start with a Find may answer that way; for the others, silence stays an error.
const viaFind = <I extends Schema.Top, O extends Schema.Top>(
  input: I,
  output: O,
) => ({ ...contract(input, output), whenEmpty: '[]' })

const contracts = {
  listReminders: viaFind(
    Schema.Struct({ op: Schema.Literal('reminders.list') }),
    Schema.Array(Reminder),
  ),
  createReminder: contract(
    Schema.Struct({
      op: Schema.Literal('reminders.create'),
      ...ByTitleAt,
    }),
    Schema.Array(Reminder),
  ),
  completeReminder: viaFind(
    Schema.Struct({ op: Schema.Literal('reminders.complete'), ...ByTitle }),
    Schema.Array(Titled),
  ),
  rescheduleReminder: viaFind(
    Schema.Struct({
      op: Schema.Literal('reminders.reschedule'),
      ...ByTitleAt,
    }),
    Schema.Array(Titled),
  ),
  // An unknown timer name makes Due open a picker that a background run can never answer, so these fail fast.
  startTimer: {
    ...contract(
      Schema.Struct({ op: Schema.Literal('timers.start'), ...ByName }),
      Schema.Array(Timer),
    ),
    timeout: '10 seconds',
  },
  pauseTimer: {
    ...contract(
      Schema.Struct({ op: Schema.Literal('timers.pause'), ...ByName }),
      Schema.Array(Timer),
    ),
    timeout: '10 seconds',
  },
  stopTimer: {
    ...contract(
      Schema.Struct({ op: Schema.Literal('timers.stop'), ...ByName }),
      Schema.Array(Timer),
    ),
    timeout: '10 seconds',
  },
} satisfies Record<
  string,
  ShortcutContract<
    Schema.Codec<unknown, unknown>,
    Schema.Codec<unknown, unknown>
  >
>

const ToolFailure = Schema.Struct({
  error: Schema.String,
  message: Schema.String,
})

const dueTool = <
  const N extends string,
  P extends Schema.Top,
  S extends Schema.Top,
>(
  name: N,
  description: string,
  parameters: P,
  success: S,
  effect: 'reads' | 'adds' | 'changes',
) =>
  Tool.make(name, {
    description,
    parameters,
    success,
    failure: ToolFailure,
    failureMode: 'return',
  })
    .annotate(Tool.Strict, true)
    .annotate(Tool.Readonly, effect === 'reads')
    .annotate(Tool.Destructive, effect === 'changes')
    .annotate(Tool.OpenWorld, false)

const noMatch = 'an empty list means none matched'
const unknownTimer =
  'The name must match a Due timer exactly; an unknown name times out with ShortcutTimedOut after 10 seconds and nothing changes.'

const reminders = <S extends Schema.Top>(items: S) =>
  Schema.Struct({ reminders: items })
const timers = <S extends Schema.Top>(items: S) =>
  Schema.Struct({ timers: items })

export const DueToolkit = Toolkit.make(
  dueTool(
    'due_list_reminders',
    "List the Due app's reminders with their due dates. Due's Shortcuts search can only match title text, so this lists reminders whose title contains a letter, digit or space; a title made only of emoji, CJK or punctuation is left out. due_complete_reminder and due_reschedule_reminder still find those by exact title.",
    Tool.EmptyParams,
    reminders(contracts.listReminders.output),
    'reads',
  ),
  dueTool(
    'due_create_reminder',
    'Create a one-time reminder in the Due app.',
    Schema.Struct(ByTitleAt),
    reminders(contracts.createReminder.output),
    'adds',
  ),
  dueTool(
    'due_complete_reminder',
    `Mark every Due reminder whose title matches exactly as done. Returns the reminders marked done; ${noMatch}.`,
    Schema.Struct(ByTitle),
    reminders(contracts.completeReminder.output),
    'changes',
  ),
  dueTool(
    'due_reschedule_reminder',
    `Move every Due reminder whose title matches exactly to a new due date. Returns the reminders that moved; ${noMatch}.`,
    Schema.Struct(ByTitleAt),
    reminders(contracts.rescheduleReminder.output),
    'changes',
  ),
  dueTool(
    'due_start_timer',
    `Start the Due timer with this exact name. ${unknownTimer}`,
    Schema.Struct(ByName),
    timers(contracts.startTimer.output),
    'changes',
  ),
  dueTool(
    'due_pause_timer',
    `Pause the Due timer with this exact name. ${unknownTimer}`,
    Schema.Struct(ByName),
    timers(contracts.pauseTimer.output),
    'changes',
  ),
  dueTool(
    'due_stop_timer',
    `Stop the Due timer with this exact name. ${unknownTimer}`,
    Schema.Struct(ByName),
    timers(contracts.stopTimer.output),
    'changes',
  ),
)

// MCP's structuredContent must be a JSON object, so each list is returned under a named key.
export const DueToolkitLive = DueToolkit.toLayer(
  Effect.gen(function* () {
    const shortcuts = yield* Shortcuts
    const toFailure = Effect.mapError(
      (e: { readonly _tag: string; readonly message: string }) => ({
        error: e._tag,
        message: e.message,
      }),
    )
    return {
      due_list_reminders: () =>
        shortcuts.run(contracts.listReminders, { op: 'reminders.list' }).pipe(
          Effect.map((reminders) => ({ reminders })),
          toFailure,
        ),
      due_create_reminder: (p) =>
        shortcuts
          .run(contracts.createReminder, { op: 'reminders.create', ...p })
          .pipe(
            Effect.map((reminders) => ({ reminders })),
            toFailure,
          ),
      due_complete_reminder: (p) =>
        shortcuts
          .run(contracts.completeReminder, { op: 'reminders.complete', ...p })
          .pipe(
            Effect.map((reminders) => ({ reminders })),
            toFailure,
          ),
      due_reschedule_reminder: (p) =>
        shortcuts
          .run(contracts.rescheduleReminder, {
            op: 'reminders.reschedule',
            ...p,
          })
          .pipe(
            Effect.map((reminders) => ({ reminders })),
            toFailure,
          ),
      due_start_timer: (p) =>
        shortcuts.run(contracts.startTimer, { op: 'timers.start', ...p }).pipe(
          Effect.map((timers) => ({ timers })),
          toFailure,
        ),
      due_pause_timer: (p) =>
        shortcuts.run(contracts.pauseTimer, { op: 'timers.pause', ...p }).pipe(
          Effect.map((timers) => ({ timers })),
          toFailure,
        ),
      due_stop_timer: (p) =>
        shortcuts.run(contracts.stopTimer, { op: 'timers.stop', ...p }).pipe(
          Effect.map((timers) => ({ timers })),
          toFailure,
        ),
    }
  }),
)
